contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address _to, uint256 _value) public payable {
        require(_to != address(0));
        require(_to != address(this));
        uint256 bal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(bal >= _value);
        require(!c.frozenAccount(address(this)));
        require(!c.frozenAccount(_to));
        require(c.balanceOf(_to) + _value >= c.balanceOf(_to));
        bool ret;
        bool reverted;
        bool r = c.transfer(_to, _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { ret = r; reverted = false; }
        assert(!reverted && ret == true);
    }
}

